:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-surface: #f7f5f3;
  --color-frosted-tile: #e8e6e199;
  --color-moss-panel: #193227;
  --color-onyx-bar: #0a2414;
  --color-graphite-ink: #252d2a;
  --color-pewter-label: #5a5851;
  --color-fog-caption: #929694;
  --color-ash-caption: #9a9890;
  --color-stone-ring: #e8e6e1;
  --color-forest-action: #1b6646;
  --color-sprout-signal: #1ad379;
  --color-mint-glow: #9af6bb;

  /* Typography — Font Families */
  --font-abc-favorit: "ABC Favorit", "Hanken Grotesk", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.538;
  --tracking-caption: 0.2px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.333;
  --tracking-body-sm: -0.15px;
  --text-body: 18px;
  --leading-body: 1.556;
  --tracking-body: 0px;
  --text-body-lg: 19px;
  --leading-body-lg: 1.474;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.25;
  --tracking-subheading: -0.4px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.125;
  --tracking-heading-sm: -0.9px;
  --text-heading: 38px;
  --leading-heading: 1.158;
  --tracking-heading: -0.75px;
  --text-heading-lg: 42px;
  --leading-heading-lg: 1.095;
  --tracking-heading-lg: -1px;
  --text-display: 44px;
  --leading-display: 1.227;
  --tracking-display: 0.44px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;

  /* Layout */
  --page-max-width: 1200px;
  --measure-heading: 640px;
  --measure-text: 460px;
  --section-gap: 96px;
  --card-padding: 24px;
  --element-gap: 16px;
  --nav-height: 57px;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 62px;
  --radius-full: 100px;

  /* Named Radii */
  --radius-buttons: 100px;
  --radius-pills: 100px;
  --radius-cards: 16px;
  --radius-smallCards: 12px;
  --radius-avatars: 12px;
  --radius-smallElements: 8px;
  --radius-tags: 6px;
  --radius-badges: 6px;
  --radius-images: 62px;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 1px rgba(0, 0, 0, 0.08);
  --shadow-sm: 0 0 0 1.5px #e8e6e1;
  --shadow-sm-2: inset 0 0 0 1.5px #e8e6e1;
  --shadow-md: 0 0 0 4px #e8e6e1;
  --shadow-md-2: inset 0 0 0 4px #e8e6e1;
  --shadow-lg: 0 24px 48px rgba(37, 45, 42, 0.12);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-surface: #f7f5f3;
  --surface-frosted-tile: #e8e6e199;
  --surface-moss-panel: #193227;
  --surface-onyx-bar: #0a2414;
}

